add_filter( 'woocommerce_cart_shipping_method_full_label', 'perfectpixel_shipping_label_link', 10, 2 );

function perfectpixel_shipping_label_link( $label, $method ) {
	$url = '{{shipping_link_url}}';
	if ( 0 === strpos( $url, '/' ) ) {
		$url = home_url( $url );
	}
	return $label . sprintf(
		' <a href="%1$s" class="perfectpixel-shipping-link" target="_blank" rel="noopener">%2$s</a>',
		esc_url( $url ),
		esc_html( '{{shipping_link_text}}' )
	);
}
